function mean(a){var s=0;for(var i=0;i<a.length;i++)s+=a[i];return s/a.length;}
function variance(a){var m=mean(a),s=0;for(var i=0;i<a.length;i++){var d=a[i]-m;s+=d*d;}return s/(a.length-1);}
function cohenD(x,y){ var nx=x.length,ny=y.length;
  var sp=Math.sqrt(((nx-1)*variance(x)+(ny-1)*variance(y))/(nx+ny-2));
  if(sp===0) return 0; return (mean(x)-mean(y))/sp; }
var EXPORTS={mean:mean,variance:variance,cohenD:cohenD};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CohenDForgePure = EXPORTS; }
